import { OutsourceDriverDataResponse } from "@/types";
import { api } from "../axios";

export const getOutsouceDrivers =
  async (): Promise<OutsourceDriverDataResponse> => {
    try {
      const res = await api.get("/api/users/admin/drivers?outsourcing=true");
      return res.data;
    } catch (error) {
      console.error("Fetch All Users Error:", error);
      // Return a default structure
      return { data: [], total: 0 } as unknown as OutsourceDriverDataResponse;
    }
  };
